// в пакете notifier: только то, что нужно этому пакету
type Sender interface {
    Send(ctx context.Context, to, text string) error
}

type Notifier struct{ sender Sender }

// *smtp.Client, *sms.Gateway, fakeSender в тестах — все подходят,
// если у них есть метод Send с такой сигнатурой

type Shape interface{ Area() float64 }

type Square struct{ side float64 }
func (s *Square) Area() float64 { return s.side * s.side }

var a Shape = &Square{2}   // ок
var b Shape = Square{2}    // ошибка: Area has pointer receiver
